LOG_STEP_IN "- Adding S21 (p3sxxx) MIDAS"
DELETE_FROM_WORK_DIR "vendor" "etc/midas"
DELETE_FROM_WORK_DIR "vendor" "etc/VslMesDetector"
ADD_TO_WORK_DIR "p3sxxx" "vendor" "etc/midas"
ADD_TO_WORK_DIR "p3sxxx" "vendor" "etc/VslMesDetector"
LOG_STEP_OUT

# SOURCE_CODENAME is not generated by sixteen-qpr2. Derive the real
# donor device from extracted firmware rather than guessing its codename.
SOURCE_FW_PATH="$(cut -d "/" -f 1 -s <<< "$SOURCE_FIRMWARE")_$(cut -d "/" -f 2 -s <<< "$SOURCE_FIRMWARE")"
S10_SOURCE_DEVICE="$(GET_PROP "$FW_DIR/$SOURCE_FW_PATH/vendor/build.prop" "ro.product.vendor.device")"
if [[ -z "$S10_SOURCE_DEVICE" ]] || [[ ! "$S10_SOURCE_DEVICE" =~ ^[a-zA-Z0-9_]+$ ]]; then
    ABORT "Could not determine source vendor codename for MIDAS"
fi
LOG "- Fixing MIDAS model detection"
sed -i "s/$S10_SOURCE_DEVICE/dummy/g" "$WORK_DIR/vendor/etc/midas/midas_config.json"
sed -i "s/p3s/$S10_SOURCE_DEVICE/g" "$WORK_DIR/vendor/etc/midas/midas_config.json"
unset S10_SOURCE_DEVICE SOURCE_FW_PATH

LOG_STEP_IN "- Adding S21 (p3sxxx) Photo Remaster Service"
DELETE_FROM_WORK_DIR "system" "system/priv-app/PhotoRemasterService/oat"
ADD_TO_WORK_DIR "p3sxxx" "system" "system/priv-app/PhotoRemasterService/PhotoRemasterService.apk"
LOG_STEP_OUT

LOG_STEP_IN "- Adding S21 (p3sxxx) MIDAS libraries"
ADD_TO_WORK_DIR "p3sxxx" "system" "system/lib64/libmidas_core.camera.samsung.so"
ADD_TO_WORK_DIR "p3sxxx" "system" "system/lib64/libmidas_DNNInterface.camera.samsung.so"
LOG_STEP_OUT
